  // munge of vocab_dic.sen

  sFileContents =
    "\""
    "\\\"munged vocab_dic.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* vocab_dic.sen -- dictionary related words                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" vocab_dic.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* folder is used as a kind of word to identify folders                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder ;\n"
    "\n"
    ": isFolder word.category@ tick folder eql ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create the tenant dictionary using name from input(doesnt leave dic on stk)*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicTenants:\n"
    "\n"
    "diclock.grabwrite\n"
    "\n"
    "  createTenants\n"
    "  WK_OBJECT compiler::current word.kind!\n"
    "  sizeof_dic allot\n"
    "  compiler::current >body object.magic!\n"
    "  CN_DIC compiler::current >body object.class!\n"
    "  tick folder compiler::current word.category!\n"
    "  compiler::current >body dic.init\n"
    "  true compiler::current >body object.wordbody!\n"
    "\n"
    "  //compiler::current word.name@ \\\"  dic: %v\\\" str.format .\n"
    "\n"
    "diclock.dropwrite\n"
    "  does>\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a dictionary using name from input stream (doesnt leave dic on stk) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dic:\n"
    "\n"
    "diclock.grabwrite\n"
    "\n"
    "  create\n"
    "  WK_OBJECT compiler::current word.kind!\n"
    "  sizeof_dic allot\n"
    "  compiler::current >body object.magic!\n"
    "  CN_DIC compiler::current >body object.class!\n"
    "  tick folder compiler::current word.category!\n"
    "  compiler::current >body dic.init\n"
    "  true compiler::current >body object.wordbody!\n"
    "\n"
    "  //compiler::current word.name@ \\\"  dic: %v\\\" str.format .\n"
    "\n"
    "diclock.dropwrite\n"
    "  does>\n"
    " ;\n"
    "\n"
    "// - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    ": dicPersistent:\n"
    "\n"
    "diclock.grabwrite\n"
    "\n"
    "  createPersistent\n"
    "  WK_OBJECT compiler::current word.kind!\n"
    "  sizeof_dic allot\n"
    "  compiler::current >body object.magic!\n"
    "  CN_DIC compiler::current >body object.class!\n"
    "  tick folder compiler::current word.category!\n"
    "  compiler::current >body dic.init\n"
    "  true compiler::current >body object.wordbody!\n"
    "\n"
    "  //compiler::current word.name@ \\\"  dic: %v\\\" str.format .\n"
    "\n"
    "diclock.dropwrite\n"
    "\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a dictionary using name on the stack (leaves dic on stack)          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :dic\n"
    "\n"
    "diclock.grabwrite\n"
    "\n"
    "  >create\n"
    "  WK_OBJECT compiler::current word.kind!\n"
    "  sizeof_dic allot\n"
    "  compiler::current >body object.magic!\n"
    "  CN_DIC compiler::current >body object.class!\n"
    "  tick folder compiler::current word.category!\n"
    "  compiler::current >body dic.init\n"
    "  true compiler::current >body object.wordbody!\n"
    "  compiler::current\n"
    "\n"
    "  //compiler::current word.name@ \\\"  :dic %v\\\" str.format .\n"
    "\n"
    "diclock.dropwrite\n"
    "  does>\n"
    " ;\n"
    "\n"
    "// - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    ": :dicPersistent\n"
    "\n"
    "diclock.grabwrite\n"
    "\n"
    "  >createPersistent\n"
    "  WK_OBJECT compiler::current word.kind!\n"
    "  sizeof_dic allot\n"
    "  compiler::current >body object.magic!\n"
    "  CN_DIC compiler::current >body object.class!\n"
    "  tick folder compiler::current word.category!\n"
    "  compiler::current >body dic.init\n"
    "  true compiler::current >body object.wordbody!\n"
    "  compiler::current\n"
    "\n"
    "  //compiler::current word.name@ \\\"  :dic %v\\\" str.format .\n"
    "\n"
    "diclock.dropwrite\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsDic ( word )\n"
    "\n"
    "  params| pWord |\n"
    "\n"
    "  pWord not if EC_NO_SUCH_FOLDER false exit_rt then\n"
    "  pWord word.category@ tick folder eql if true exit_rt then\n"
    "  EC_NOT_A_FOLDER false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicHasRef ( word )\n"
    "\n"
    "  dup execute dic.ref\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check dic not in use                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkNotUsed ( dic -- true | error false )\n"
    "\n"
    "  //dicHasRef \\\" dic ref \\\" .put .put .\\\\n\n"
    "\n"
    "  dicHasRef if EC_FOLDER_IN_USE false exit_rt then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check dic is empty                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsEmpty ( dic -- true | error false )\n"
    "\n"
    "  dup execute dic.wordCount if EC_FOLDER_NOT_EMPTY false exit_rt then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT vocab_dic.sen"_Stz
  ;

