    "*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump the return stack                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": rstk_w\n"
    "\n"
    "  \\\"return stack\\\" .\n"
    "  rdepth dup not if drop exit_rt then\n"
    "  0 do\n"
    "    I 2 + rpick\n"
    "    dup .put\n"
    "    \\\" \\\".put\n"
    "    locate\n"
    "    dup if .put else drop then\n"
    "    .\\\\n\n"
    "  loop\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* interpret string on stack                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >: input::push input::text docol input::pop ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check for known word                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsWord ( <\\\"wordNm\\\"> )\n"
    "  find\n"
    "  not if EC_NO_SUCH_WORD false exit_rt then\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test type of top stack value                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": isType ( CN_ -- bool )\n"
    "\n"
    "  // false if stack empty\n"
    "  depth 2 >= not if drop false exit_rt then\n"
    "\n"
    "  // no more if not indirect\n"
    "  1 stack.class ==\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT vocab_debug.sen"_Stz
  ;

