  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of jobSuffix.sen

  sFileContents =
    "\""
    "\\\"munged jobSuffix.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* jobSuffix.sen -- Job Suffixes                                              */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" jobSuffix.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* append a suffix to name of word being compiled                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": word::addSuffix params| sSuffix |\n"
    "\n"
    "  compiler::current word.name@ sSuffix str.cat compiler::current word.name!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* category of words which are seeds                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": seed\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* sets the category of word being being compiled as seed                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": word::seed#\n"
    "\n"
    "  tick seed compiler::current word.category!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* suffix sets the category of word being being compiled as suffix            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": suffix immediate\n"
    "\n"
    "  tick suffix compiler::current word.category!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* _req makes the word being compile a request seed with name: <wordNm>_req   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _req immediate suffix\n"
    "\n"
    "  // append _req to name of word being compiled\n"
    "  \\\"_req\\\" word::addSuffix\n"
    "\n"
    "  word::seed#\n"
    "\n"
    "  // set exit hook of word being compiled\n"
    "  \\\"req_exitHook\\\" compiler::current word.exitHook!\n"
    "\n"
    "  // add call to req_entryHook into word being compiled\n"
    "  POSTPONE req_entryHook\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* _beg makes the word being compile a seed with name: <wordNm>_beg           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _beg immediate suffix\n"
    "\n"
    "  // append _beg to name of word being compiled\n"
    "  \\\"_beg\\\" word::addSuffix\n"
    "\n"
    "  // the compiled word is a seed\n"
    "  tick seed compiler::current word.category!\n"
    "\n"
    "  word::seed#\n"
    "\n"
    "  // set exit hook of word being compiled\n"
    "  \\\"beg_exitHook\\\" compiler::current word.exitHook!\n"
    "\n"
    "  // add call to beg_entryHook into word being compiled\n"
    "  POSTPONE beg_entryHook\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* _exe makes the word being compile a seed with name: <wordNm>_exe           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _exe immediate suffix\n"
    "\n"
    "  // append _exe to name of word being compiled\n"
    "  \\\"_exe\\\" word::addSuffix\n"
    "\n"
    "  word::seed#\n"
    "\n"
    "  // set exit hook of word being compiled\n"
    "  \\\"exe_exitHook\\\" compiler::current word.exitHook!\n"
    "\n"
    "  // add call to exe_entryHook into word being compiled\n"
    "  POSTPONE exe_entryHook\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* _end makes the word being compile a end seed with name: <wordNm>_end       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _end immediate suffix\n"
    "\n"
    "  // append _end to name of word being compiled\n"
    "  \\\"_end\\\" word::addSuffix\n"
    "\n"
    "  word::seed#\n"
    "\n"
    "  // set exit hook of word being compiled\n"
    "  \\\"end_exitHook\\\" compiler::current word.exitHook!\n"
    "\n"
    "  // add call to end_entryHook into word being compiled\n"
    "  POSTPONE end_entryHook\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* _can makes the word being compile a cancel seed with name: <wordNm>_can    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _can immediate suffix\n"
    "\n"
    "  // append _can to name of word being compiled\n"
    "  \\\"_can\\\" word::addSuffix\n"
    "\n"
    "  word::seed#\n"
    "\n"
    "  // set exit hook of word being compiled\n"
    "  \\\"can_exitHook\\\" compiler::current word.exitHook!\n"
    "\n"
    "  // add call to can_entryHook into word being compiled\n"
    "  POSTPONE can_entryHook\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* _run makes the word being compile a seed with name: <wordNm>_run           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _run immediate suffix\n"
    "\n"
    "  // append _beg to name of word being compiled\n"
    "  \\\"_run\\\" word::addSuffix\n"
    "\n"
    "  word::seed#\n"
    "\n"
    "  // set exit hook of word being compiled\n"
    "  \\\"run_exitHook\\\" compiler::current word.exitHook!\n"
    "\n"
    "  // add call to beg_entryHook into word being compiled\n"
    "  POSTPONE run_entryHook\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* adds a standard entry and exit hook to word being compiled                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _eeh immediate suffix\n"
    "\n"
    "  \\\"std_exitHook\\\" compiler::current word.exitHook!\n"
    "\n"
    "  // add call to std_entryHook into word being compiled\n"
    "  POSTPONE std_entryHook\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT jobSuffix.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_SubFetch.sen

  sFileContents =
    "\""
    "\\\"munged job_SubFetch.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_SubFetch.sen -- Job SubFetch                                           */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_SubFetch.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* fetch rows                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetchRows ( Job_SubFetch -- <R> )\n"
    "\n"
    "  params| pJob_SubFetch |\n"
    "  0 0 0 locals| sTableNm iPhrase iSlot |\n"
    "  0 0 0 0 locals| pPlanner pBufferQueue pIndex pTable |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the planner, bufferQueue, phrase and slot t\n"
    "  pJob_SubFetch job_subFetch.planner@ to pPlanner\n"
    "  pJob_SubFetch job_subFetch.bufferQueue@ to pBufferQueue\n"
    "  pJob_SubFetch job_subFetch.phrase@ to iPhrase\n"
    "  pJob_SubFetch job_subFetch.slot@ to iSlot\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table\n"
    "  //pJob_SubFetch job.objectName@ to sTableNm\n"
    "  <tableNm> to sTableNm\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // find the table\n"
    "  sTableNm find execute to pTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push into indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  iPhrase pPlanner Planner.fetchTechnique@\n"
    "  case\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // an exact select using index\n"
    "    AT_EXACT of\n"
    "      // find the index\n"
    "      iPhrase pPlanner Planner.indexNm@\n"
    "      find execute to pIndex\n"
    "\n"
    "      // now get excat key rows from index\n"
    "      iSlot pTable tablePtnGrabRead  //! partitionLock\n"
    "      iPhrase pPlanner Planner.key@\n"
    "      iPhrase pPlanner Planner.key@\n"
    "      pJob_SubFetch pIndex index.range\n"
    "      iSlot pTable tablePtnDropRead\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // lower bound select using index\n"
    "    AT_LOWER of\n"
    "      // find the index\n"
    "      iPhrase pPlanner Planner.indexNm@\n"
    "      find execute to pIndex\n"
    "\n"
    "      // now get excat key rows from index\n"
    "      iSlot pTable tablePtnGrabRead  //! partitionLock\n"
    "      iPhrase pPlanner Planner.lowKey@\n"
    "      pJob_SubFetch pIndex index.lowerBound\n"
    "      iSlot pTable tablePtnDropRead\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // an upper bound select using index\n"
    "    AT_UPPER of\n"
    "\n"
    "      // find the index\n"
    "      iPhrase pPlanner Planner.indexNm@\n"
    "      find execute to pIndex\n"
    "\n"
    "      // now get excat key rows from index\n"
    "      iSlot pTable tablePtnGrabRead  //! partitionLock\n"
    "      iPhrase pPlanner Planner.highKey@\n"
    "      pJob_SubFetch pIndex index.upperBound\n"
    "      iSlot pTable tablePtnDropRead\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // a range select using index\n"
    "    AT_RANGE of\n"
    "\n"
    "      // find the index\n"
    "      iPhrase pPlanner Planner.indexNm@\n"
    "      find execute to pIndex\n"
    "\n"
    "      // now get excat key rows from index\n"
    "      iSlot pTable tablePtnGrabRead  //! partitionLock\n"
    "      iPhrase pPlanner Planner.highKey@\n"
    "      iPhrase pPlanner Planner.lowKey@\n"
    "      pJob_SubFetch pIndex index.range\n"
    "      iSlot pTable tablePtnDropRead\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // full scan (no index)\n"
    "    AT_SCAN of\n"
    "\n"
    "      // now scan the table\n"
    "      iSlot pTable tablePtnGrabRead  //! partitionLock\n"
    "      pJob_SubFetch pTable table.scan\n"
    "      iSlot pTable tablePtnDropRead\n"
    "    endof\n"
    "\n"
    "  endcase\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table\n"
    "  popTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes\n"
    "  popIndexes\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* SubFetch (on originating node)                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": SubFetch_run ( -- <R> )\n"
    "\n"
    "  >>logEntry <SEED_RUN>\n"
    "\n"
    "  0 0 locals| pTask pJob_SubFetch |\n"
    "\n"
    "  //\\\"SubFetch_run\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_SubFetch\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // execute fetch depending on the fetchTechnique in the planner\n"
    "  pJob_SubFetch fetchRows\n"
    "\n"
    "  DdlLock[].testDrop\n"
    "\n"
    "  <DONE_RUN>\n"
    "  job::completed\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_SubFetch.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_Cf.sen

  sFileContents =
    "\""
    "\\\"munged job_Cf.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Cf.sen -- Job Change Folder                                            */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Cf.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cf command request                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": cf_req ( -- )\n"
    "\n"
    "  >>logEntry <SEED_REQ>\n"
    "\n"
    "  0 0 0 0 locals| pCurrentFolder sFolderNm pJob_Cf pTask |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_Cf\n"
    "\n"
    "  // get the folderNm from the job\n"
    "  //pJob_Cf job.folderName@ to sFolderNm\n"
    "  <folderNm> to sFolderNm\n"
    "\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // test for a \\\"..\\\" which will go up one folder\n"
    "\n"
    "  // pop up one folder, but not into tenants\n"
    "  sFolderNm \\\"..\\\" str.equal if\n"
    "    pathCurrentFolder dic.name \\\"tenants\\\" str.equal not if pathDrop then\n"
    "    setPath\n"
    "    <<logExit <DONE_REQ>\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // test for a \\\"~\\\" will pop folder path till it reaches /tenants\n"
    "\n"
    "  // pop up to tenants\n"
    "  sFolderNm \\\"~\\\" str.equal if\n"
    "    begin pathCurrentFolder dic.name \\\"tenants\\\" str.equal not while pathDrop repeat\n"
    "    setPath\n"
    "    <<logExit <DONE_REQ>\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // test for a \\\"tenants\\\" will clear folder path and set to /tenants\n"
    "\n"
    "  // clear dic path and push tenants\n"
    "  sFolderNm \\\"tenants\\\" str.equal if\n"
    "    pathDropAll\n"
    "    attachmap::tenants@ execute pathPush\n"
    "    setPath\n"
    "    <<logExit <DONE_REQ>\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // otherwise we expect a name of a sub-folder to which we push path to\n"
    "  //  push sub-folder\n"
    "\n"
    "  sFolderNm findInCurrent to pCurrentFolder\n"
    "  pCurrentFolder checkIsDic not if pJob_Cf <ERROR_REQUEST> !!logError exit then\n"
    "  pCurrentFolder execute pathPush\n"
    "  setPath\n"
    "  <<logExit <DONE_REQ>\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: cf :: cf <folderNm> ;\n"
    "\n"
    "jobInfo: cf\n"
    "{\n"
    "  <?jobDesc?>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <?jobType?>  = JT_CF\n"
    "  <?jobKind?>  = JK_LOCAL\n"
    "  <?rspKind?>  = RS_LOCAL_ERRORS\n"
    "  <?ddlLock?>  = DL_GRAB_READ\n"
    "  \n"
    "  <?preCheck?> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Cf.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_InsertTable.sen

  sFileContents =
    "\""
    "\\\"munged job_InsertTable.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_InsertTable.sen -- Job Insert Table                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_InsertTable.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send last buffers to all partitions                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": InsertTable_sendLast ( pJob_InsertTable -- )\n"
    "\n"
    "  params| pJob_InsertTable  |\n"
    "  0 0 locals| pThisTask pJob_SubInserter |\n"
    "\n"
    "  task::this to pThisTask\n"
    "\n"
    "  // calculate total partitions in the cluster\n"
    "  grid::slots grid::definedNodes * locals| nTotalPartitions |\n"
    "\n"
    "  pJob_InsertTable job_InsertTable.SubInserterJob@ to pJob_SubInserter\n"
    "  //pJob_InsertRowss .\n"
    "\n"
    "  // grab this task's lock\n"
    "  pThisTask task.grabLock\n"
    "\n"
    "  grid::slots task::acks!\n"
    "\n"
    "  //pJob_SubInserter Job_SubInserter.end\n"
    "\n"
    "  //\\\"InsertTable_sendLast ack waiting\\\" .verbose\n"
    "  task::wait\n"
    "  //\\\"InsertTable_sendLast acked\\\" .verbose\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* wait for ack only                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": InsertTable_waitOnly ( pJob_InsertTable --  )\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab this task's lock\n"
    "  task::this task.grabLock\n"
    "\n"
    "  grid::slots task::acks!\n"
    "\n"
    "  //\\\"InsertTable_waitOnly waiting\\\" .verbose\n"
    "  task::wait\n"
    "  //\\\"InsertTable_waitOnly acked\\\" .verbose\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* Job_InsertTable request (on originating node)                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": insertTable_req (  -- <R> )\n"
    "\n"
    "  >>logEntry 2\n"
    "\n"
    "  0 0 locals| pJob pTask |\n"
    "\n"
    "\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob\n"
    "\n"
    "  // distribute the job\n"
    "  pJob job.distribute\n"
    "\n"
    "  <<logExit <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_InsertTable job on each node                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": insertTable_exe ( Job_InsertTable -- )\n"
    "\n"
    "  >>logEntry <SEED_EXE>\n"
    "\n"
    "  job::this locals| pJob_InsertTable |\n"
    "\n"
    "  0 0 locals| pTable sTableNm |\n"
    "\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // assert correct job\n"
    "  CN_JOB_INSERTTABLE pJob_InsertTable object.assertClass\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // grab a lock ????\n"
    "\n"
    "  pJob_InsertTable job::originator@ locals| iOriginNode |\n"
    "  grid::thisNode@ locals| iThisNode |\n"
    "\n"
    "  //iThisNode iOriginNode \\\"Originating node %v; this node %v\\\" .printf\n"
    "  \n"
    "  iThisNode iOriginNode == if\n"
    "    //\\\"InsertTable is executing on this node\\\" .\n"
    "    pJob_InsertTable InsertTable_sendLast\n"
    "  else\n"
    "    //\\\"InsertTable is not executed on this node\\\" .\n"
    "    InsertTable_waitOnly\n"
    "  then\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  pJob_InsertTable job.notice\n"
    "\n"
    "  // job::deleteThis\n"
    "\n"
    "  pJob_InsertTable job::participantExecuted\n"
    "\n"
    "  <<logExit <DONE_EXE>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_InsertTable job check resources                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": insertTable.checkResources ( pJob_InsertTable -- )\n"
    "\n"
    "  params| pJob_InsertTable  |\n"
    "\n"
    "  //checkResources received\\\" .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_InsertTable job release resources                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": insertTable.releaseResources ( pJob_InsertTable -- )\n"
    "\n"
    "  //releaseResources received\\\" .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": insertTable_beg ( -- )\n"
    "\n"
    "  >>logEntry <SEED_BEG>\n"
    "\n"
    "  job::this locals| pJob_InsertTable |\n"
    "\n"
    "  \\\">> insertTable_beg <<\\\" .verbose\n"
    "\n"
    "  // add this job to the participants list\n"
    "  pJob_InsertTable job.becomeParticipant\n"
    "\n"
    "  // check resources\n"
    "  pJob_InsertTable insertTable.checkResources\n"
    "\n"
    "  // this job has begun\n"
    "  job::participantBegun\n"
    "\n"
    "  <<logExit <DONE_BEG>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": insertTable_end ( -- )\n"
    "\n"
    "  >>logEntry <SEED_END>\n"
    "\n"
    "  job::this locals| pJob_InsertTable |\n"
    "\n"
    "  \\\">> insertTable_end <<\\\" .verbose\n"
    "\n"
    "  // release resources\n"
    "  pJob_InsertTable insertTable.releaseResources\n"
    "\n"
    "  job::participantEnded\n"
    "\n"
    "  <<logExit <DONE_END>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": insertTable_can ( -- )\n"
    "\n"
    "  >>logEntry <SEED_CAN>\n"
    "\n"
    "  job::this locals| pJob_InsertTable |\n"
    "\n"
    "  pJob_InsertTable insertTable.releaseResources\n"
    "\n"
    "  job::participantCancelled\n"
    "\n"
    "  <<logExit <DONE_CAN>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_InsertTable.sen"_Stz
  ;

  vCompileConstant(sFileContents);


