  // munge of job_VerifyTable.sen

  sFileContents =
    "\""
    "\\\"munged job_VerifyTable.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_VerifyTable.sen -- Job Verify Table                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_VerifyTable.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a valid table folder                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkverifyTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWord not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "  //sTableNm tableInUse if popTable EC_TABLE_IN_USE false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table folder\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify table request on a node                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": verifyTable::execute _eeh ( -- )\n"
    "\n"
    "  job::this locals| pjob_VerifyTable |\n"
    "\n"
    "  0 0 locals| pTask sTableNm  |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the tablen ame\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // verify the table\n"
    "  sTableNm find execute table.verify\n"
    "  sTableNm grid::thisNodeName@\n"
    "  \\\"row: ('%v', '%v', '%v')\\\\n\\\" str.format\n"
    "  pjob_VerifyTable job.response!\n"
    "  1 pjob_VerifyTable job.rowsProcessed!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table folder\n"
    "  popIndexes\n"
    "  popTable\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute job_VerifyTable job check resources                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": verifyTable::checkResources _eeh ( -- )\n"
    "  0 0 locals| sIndexNm sTableNm |\n"
    "\n"
    "  //checkResources received\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "<tableNm> checkverifyTable not if job::this <ERROR_JOB> !!logError exit then\n"
    "\n"
    "  DdlLock[].dropRead\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "jobSyntax: verifyTable :: verifyTable <tableNm> ;\n"
    "jobSyntax: verifyTable :: vfyTbl <tableNm> ;\n"
    "\n"
    "jobInfo: verifyTable\n"
    "{\n"
    "  <?jobDesc?>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <?jobType?>  = JT_VERIFYTABLE\n"
    "  <?jobKind?>  = JK_DIST2PC\n"
    "  <?rspKind?>  = RS_NODE_ROWS\n"
    "  <?ddlLock?>  = DL_GRAB_READ\n"
    "  \n"
    "  <?preCheck?> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_VerifyTable.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_SubTruncate.sen

  sFileContents =
    "\""
    "\\\"munged job_SubTruncate.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_SubTruncate.sen -- Job SubTruncate                                     */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_SubTruncate.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* SubTruncate (on each node)                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": SubTruncate_run ( -- <R> )\n"
    "\n"
    "  >>logEntry <SEED_RUN>\n"
    "\n"
    "  0 0 locals| pJob_SubTruncate pTask |\n"
    "  0 0 0 locals| iSlot pTable sTableNm |\n"
    "  0 0 locals| iTrucateJobId pJob_TruncateTable |\n"
    "\n"
    "  //\\\"SubTruncate_run\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job\n"
    "  job::this to pJob_SubTruncate\n"
    "\n"
    "  // get truncate job\n"
    "  pJob_SubTruncate job_SubTruncate.truncateJobId@ to iTrucateJobId\n"
    "  pJob_SubTruncate iTrucateJobId job::waitParticipant to pJob_TruncateTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // first check if the job is executing SS_SEED_EXE\n"
    "  // then get the task that is executing it\n"
    "  begin\n"
    "    pJob_TruncateTable job.IsExecuting\n"
    "  not while\n"
    "    1 thread::sleepMsec\n"
    "  repeat\n"
    "\n"
    "  pJob_TruncateTable job.task@ locals| pTask_TruncateTable |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // wait for acks to be set in the truncate task\n"
    "  begin\n"
    "    pTask_TruncateTable task.IsAckSet\n"
    "  not while\n"
    "    1 thread::sleepMsec\n"
    "  repeat\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // find the table\n"
    "  sTableNm find execute to pTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the slot this sub truncate is supposed to work on\n"
    "  pJob_SubTruncate job_subTruncate.slot@ to iSlot\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // truncate table for iSlot\n"
    "  iSlot pTable table.truncate\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table\n"
    "  popTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // notify the truncate job\n"
    "  pTask_TruncateTable task.grabLock\n"
    "  pTask_TruncateTable task.dropLock\n"
    "  pTask_TruncateTable task.ack\n"
    "\n"
    "  <DONE_RUN>\n"
    "\n"
    "  job::completed\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_SubTruncate.sen"_Stz
  ;

  vCompileConstant(sFileContents);


