    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute the job's run seed-word on each participating node                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": universal_run ( -- )\n"
    "\n"
    "  job::</seeFlow/>\n"
    "\n"
    "  \\\"<?SeedRun?>\\\" .executeSeed\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Universal.sen"_Stz
  ;

