    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // should never exit\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: service :: service ;\n"
    "\n"
    "jobInfo: service\n"
    "{\n"
    "  <?jobDesc?>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <?jobType?>  = JT_NONE\n"
    "  <?jobKind?>  = JK_LOCAL\n"
    "  <?rspKind?>  = RS_NONE\n"
    "  <?ddlLock?>  = DL_NONE\n"
    "  \n"
    "  // <?preCheck?> = bClusterStarted\n"
    "  \n"
    "  <?cmdKind?>  = CK_SERVICE\n"
    "}\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                              - Command -                               ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": serviceXXXX immediate\n"
    "\n"
    "  0 locals| nArgs |\n"
    "\n"
    "  begin\n"
    "    next-token\n"
    "  dup \\\";&\\\" str.equal not\n"
    "  while\n"
    "    nArgs ++ to nArgs\n"
    "  repeat\n"
    "\n"
    "  // drop the \\\";&\\\" from dstack\n"
    "  drop\n"
    "\n"
    "  nArgs\n"
    "\n"
    "  // \\\"would spawn service\\\" .\n"
    "\n"
    "  dropN\n"
    "\n"
    "  //compiler::current word.name@ ,\n"
    "\n"
    "  \\\"service\\\" ,\n"
    "\n"
    "  tick job::spawnUniversal compile,\n"
    "\n"
    "  //tick drop compile,\n"
    "\n"
    "  assert::stack_0\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Service.sen"_Stz
  ;

