  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of vocab_corePlus.sen

  sFileContents =
    "\""
    "\\\"munged vocab_corePlus.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* vocab_corePlus.sen -- words complentary to core words                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" vocab_corePlus.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* increment integer variable                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ++ dup @ 1+ swap ! ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* decrement integer variable                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": -- dup @ 1- swap ! ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* define a constant (using name on stack)                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :constant\n"
    "\n"
    "  // create a word using the string on top of the stack\n"
    "  >create\n"
    "\n"
    "  // encode a push value of the value currently on the stack\n"
    "  ,\n"
    "\n"
    "  // encode a push value of the value currently on the stack\n"
    "  POSTPONE exit_rt\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forget named word                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :forget ( <\\\"wordNm\\\"> )\n"
    "\n"
    "  find ( word )\n"
    "\n"
    "  dup not if drop exit_rt then ( )\n"
    "\n"
    "  word::delete ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop all values on stack except topmost                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": nipAll ( ... top -- top )\n"
    "\n"
    "  // handle expty stack case\n"
    "  depth not if exit_rt then\n"
    "\n"
    "  // save topmost\n"
    "  >r\n"
    "\n"
    "  // drop everything else\n"
    "  begin\n"
    "    depth while\n"
    "      drop\n"
    "  repeat\n"
    "\n"
    "  // restore topmost\n"
    "  r>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop n values from stack                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dropN ( ... #values -- )\n"
    "\n"
    "  // handle expty stack case\n"
    "  depth not if exit_rt then\n"
    "\n"
    "  // drop n values\n"
    "  0 ?do\n"
    "    drop\n"
    "  loop\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT vocab_corePlus.sen"_Stz
  ;

  vCompileConstant(sFileContents);


