  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_Mark2Op.sen

  sFileContents =
    "\""
    "\\\"munged job_Mark2Op.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Mark2Op.sen -- Mark II Operator Experiment                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Mark2Op.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* mark2op request                                    (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : mark2op_req ( -- )\n"
    " \n"
    "   >>logEntry <SEED_REQ>\n"
    "\n"
    "   job::this locals| pMark2Op |\n"
    "\n"
    "   begin\n"
    "\n"
    "    // bide till next operand is available\n"
    "    Operand[].bide\n"
    "\n"
    "    // pop next operand from queue into Operand[]\n"
    "    Operand[].next\n"
    "\n"
    "    // decode kind\n"
    "    Operand[].kind case\n"
    "\n"
    "      ZK_CRWBUFFER of\n"
    "        \\\"Operand:- ZK_CRWBUFFER\\\" .\n"
    "        Operand[].workDone\n"
    "        Operand[].pipeOut\n"
    "        true\n"
    "      endof\n"
    "\n"
    "      ZK_CSVBUFFER of\n"
    "        \\\"Operand:- ZK_CSVBUFFER\\\" .\n"
    "        Operand[].workDone\n"
    "        Operand[].pipeOut\n"
    "        true\n"
    "      endof\n"
    "\n"
    "      ZK_ENDMARKER of\n"
    "        \\\"Operand:- ZK_ENDMARKER\\\" .\n"
    "        Operand[].handleEnd\n"
    "        // *does not pipeout*\n"
    "        false\n"
    "      endof\n"
    "\n"
    "      ZK_ENTBUFFER of\n"
    "        \\\"Operand:- ZK_ENTBUFFER\\\" .\n"
    "        Operand[].workDone\n"
    "        Operand[].pipeOut\n"
    "        true\n"
    "      endof\n"
    "\n"
    "      ZK_IRWBUFFER of\n"
    "        \\\"Operand:- ZK_IRWBUFFER\\\" .\n"
    "        Operand[].workDone\n"
    "        Operand[].pipeOut\n"
    "        true\n"
    "      endof\n"
    "\n"
    "      ZK_SRTBUFFER of\n"
    "        \\\"Operand:- ZK_SRTBUFFER\\\" .\n"
    "        Operand[].workDone\n"
    "        Operand[].pipeOut\n"
    "        true\n"
    "      endof\n"
    "\n"
    "      ZK_STREAMDEF of\n"
    "        \\\"Operand:- ZK_STREAMDEF\\\" .\n"
    "        Operand[].workDone\n"
    "        Operand[].pipeOut\n"
    "        true\n"
    "      endof\n"
    "\n"
    "    endcase\n"
    "\n"
    "   while assert::stack_0 repeat\n"
    "\n"
    "  <<logExit\n"
    "  job::deleteThis\n"
    "  <DONE_RUN>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "jobSyntax: mark2op :: mark2op ;\n"
    "\n"
    "jobInfo: mark2op\n"
    "{\n"
    "  <?jobDesc?>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <?jobType?>  = JT_OUTPUTOP\n"
    "  <?jobKind?>  = JK_LOCAL\n"
    "  <?rspKind?>  = RS_NODE_ZERO\n"
    "  <?ddlLock?>  = DL_GRAB_READ\n"
    "  \n"
    "  <?preCheck?> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Mark2Op.sen"_Stz
  ;

  vCompileConstant(sFileContents);


