  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of test_gGen.sen

  sFileContents =
    "\""
    "\\\"munged test_gGen.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* test_gGen.sen -- generate gGen files                                       */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" test_gGen.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate g definitions                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gCol ( eColumn -- sColType )\n"
    "\n"
    "  params| eColumn |\n"
    "\n"
    "  eColumn case\n"
    "\n"
    "    CT_BOOLEAN   of \\\"boolean\\\"   endof\n"
    "    CT_CHAR      of \\\"char\\\"      endof\n"
    "    CT_DATE      of \\\"date\\\"      endof\n"
    "    CT_DECIMAL   of \\\"decimal\\\"   endof\n"
    "    CT_FLOAT     of \\\"float\\\"     endof\n"
    "    CT_INTEGER   of \\\"integer\\\"   endof\n"
    "    CT_INTERVAL  of \\\"interval\\\"  endof\n"
    "    CT_TIME      of \\\"time\\\"      endof\n"
    "    CT_TIMESTAMP of \\\"timestamp\\\" endof\n"
    "    CT_VARCHAR   of \\\"varchar\\\"   endof\n"
    "\n"
    "  endcase\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate g definitions                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gRecurse ( iDepth -- )\n"
    "\n"
    "  params| iDepth |\n"
    "\n"
    "  iDepth .\n"
    "\n"
    "  iDepth if\n"
    "    iDepth 1 - to iDepth\n"
    "    iDepth gRecurse\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate g definitions                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gGen\n"
    "\n"
    "  9 gRecurse\n"
    "\n"
    "  CT_ENUMS CT_BOOLEAN\n"
    "  do\n"
    "    I .\n"
    "    I gCol .\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT test_gGen.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of vocab_dicStack.sen

  sFileContents =
    "\""
    "\\\"munged vocab_dicStack.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* vocab_dicStack.sen -- dictionary stack related words                     */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" vocab_dicStack.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get depth of path                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathDepth ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // get depth\n"
    "  dicStack.depth\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop top dictionary from path                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathDrop ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // drop the top dictionary\n"
    "  dicStack.drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump the path                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathDump ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // dump the dic stack\n"
    "  dicStack.dump\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pick a dictionary from path                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathPick ( i -- dic )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // pick the dictionary from dic stack\n"
    "  dicStack.pick\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop top dictionary from path                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathPop ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // pop the top dictionary\n"
    "  dicStack.pop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* push a dictionary onto path                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathPush ( dic -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // push the dictionary onto dic stack\n"
    "  dicStack.push\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get dictionary path                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathGet ( -- ... #dics )\n"
    "\n"
    "  // this word puts the dictionary path onto the stack as a series of names\n"
    "  //   ( ... \\\"<subFolderC>\\\"  \\\"<subFolderB>\\\"  \\\"<subFolderA>\\\" 3 )\n"
    "  // note: it should not push \\\"__dicRoot\\\"\n"
    "\n"
    "  pathDepth 0 ?do\n"
    "\n"
    "    // get dictionary[I]\n"
    "    I pathPick  ( dic )\n"
    "\n"
    "    // push dictionary name\n"
    "    dic.name ( ... dicNm )\n"
    "\n"
    "  loop\n"
    "\n"
    "  // push number of dictionary names\n"
    "  pathDepth ( ... #dics )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* getcurrent folder                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathCurrentFolder ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  dicStack.depth 1 - pathPick\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list all words in the current dictionary                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": words\n"
    "\n"
    "  pathCurrentFolder dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ word.name@ .          // print the name of the word\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list all words (long form) in the current dictionary                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": symbols\n"
    "\n"
    "  pathCurrentFolder dic.lastWord\n"
    "  begin dup while\n"
    "    dup word.name@ .put \\\" \\\" .put dup word.category@ word.name@ .put .\\\\n\n"
    "    word.prev\n"
    "  repeat\n"
    "  drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get all words in the current dictionary as a single string                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listContents ( job -- )\n"
    "\n"
    "  params| pJob |\n"
    "  0 locals| iCount |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  args.metadata if\n"
    "    \\\"(name VARCHAR)\\\" pJob job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // form the row for each word\n"
    "  \\\"\\\"                               // initial contents string\n"
    "  pathCurrentFolder dic.lastWord dup\n"
    "  iterate                          // setup iteration of words\n"
    "    1 iCount + to iCount\n"
    "    \\\"row: ('\\\" str.cat\n"
    "    object@ word.name@ str.cat      // add name of the word to contents string\n"
    "    \\\"')\\\\n\\\" str.cat\n"
    "    object@ word.prev object!      // step backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set response in the job\n"
    "  pJob job.response!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // sent rows Processed in the job\n"
    "  iCount pJob job.rowsProcessed!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forget all words in given dictionary                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": forgetAll ( dic -- )\n"
    "\n"
    "  dup dic.lastWord not if drop exit_rt then\n"
    "\n"
    "  dup pathPush\n"
    "\n"
    "  begin\n"
    "\n"
    "    dup dic.lastWord word.name@ :forget\n"
    "\n"
    "    dup dic.lastWord not until\n"
    "\n"
    "  pathDrop\n"
    "\n"
    "  drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a subdictionary under given dic                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :folder ( \\\"<subDicNm>\\\" dic -- )\n"
    "\n"
    "  pathPush :dic tick folder swap execute dic.kind! pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* clear task dictionary stack                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": task::dicStack.clear\n"
    "\n"
    "  pathDepth 0 ?do\n"
    "    pathDrop\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop all dictionaries from given stack                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicStack.dropAll ( dicStack -- )\n"
    "\n"
    "  locals| dicStack |\n"
    "\n"
    "  dicStack dicStack.depth 0 ?do\n"
    "    dicStack dicStack.drop\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set task dictionary stack                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": task::dicStack.set ( ... #dics -- )\n"
    "\n"
    "  // this word puts the folder path on the stack into task dictionary stack\n"
    "  // ( ... \\\"<subFolderC>\\\"  \\\"<subFolderB>\\\"  \\\"<subFolderA>\\\" \\\"main\\\" 4 )\n"
    "\n"
    "\n"
    "  task::dicStack.clear\n"
    "\n"
    "  dup not if drop exit_rt then\n"
    "\n"
    "  0 do\n"
    "\n"
    "    // dup \\\"task::dicStack.set %v\\\" .printf\n"
    "\n"
    "    dup \\\"__dicRoot\\\" str.equal if\n"
    "      drop\n"
    "      dic.root\n"
    "      pathPush\n"
    "    else\n"
    "\n"
    "      dup \\\"session\\\" str.equal if\n"
    "        drop\n"
    "      else\n"
    "\n"
    "        dup \\\"tenants\\\" str.equal if\n"
    "          drop attachmap::tenants@ execute pathPush\n"
    "        else\n"
    "\n"
    "          find\n"
    "          execute\n"
    "          pathPush\n"
    "        then\n"
    "\n"
    "      then\n"
    "\n"
    "    then\n"
    "\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop top dictionary from path                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathDropAll ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // drop the top dictionary\n"
    "  dicStack.dropAll\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT vocab_dicStack.sen"_Stz
  ;

  vCompileConstant(sFileContents);


