  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of test_dData.sen

  sFileContents =
    "\""
    "\\\"munged test_dData.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* test_dData.sen -- generate d test data                                     */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" test_dData.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate a d data file                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dDataFile\n"
    "\n"
    "  params| nRecs |\n"
    "  params| sFileNm |\n"
    "\n"
    "  nRecs sFileNm \\\"File: %v nRecs %v\\\" .printf\n"
    "\n"
    "  file::new locals| pFile |\n"
    "\n"
    "  sFileNm OPEN_WRITE pFile file.open\n"
    "  not if\n"
    "    \\\"file not opened\\\" .\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  nRecs 0 > if\n"
    "    nRecs 0\n"
    "    do\n"
    "      //I 0 \\\"%v,String%v\\\" str.format .\n"
    "      I 0 \\\"%v,String%v\\\\n\\\" str.format pFile file.write\n"
    "    loop\n"
    "  then\n"
    "\n"
    "  pFile file.close\n"
    "\n"
    "  pFile file.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate the t data files                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dData\n"
    "\n"
    "  \\\"/rapids/d/d.csv\\\" 100000 dDataFile\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT test_dData.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_SizeIndex.sen

  sFileContents =
    "\""
    "\\\"munged job_SizeIndex.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_SizeIndex.sen -- Job Size Table                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_SizeIndex.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a valid index                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkSizeIndex ( \\\"<tableNm>\\\" \\\"<indexNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sIndexNm sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWord not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "  //sTableNm tableInUse if popTable EC_TABLE_IN_USE false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is an index we are dropping\n"
    "  sIndexNm checkIsIndex not if\n"
    "    popIndexes popTable assertInTables false exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes and table folder\n"
    "  popIndexes\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_SizeIndex job on a node                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex::execute _eeh ( -- )\n"
    "\n"
    "  //params| pJob_SizeIndex |\n"
    "  job::this locals| pJob_SizeIndex |\n"
    "\n"
    "  0 0 0 0 locals| pIndex iSize sTableNm sIndexNm |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the table and index names\n"
    "  <indexNm> to sIndexNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table and indexes folder\n"
    "  sTableNm pushTable assert\n"
    "  pushIndexes assert\n"
    "\n"
    "  sIndexNm find execute to pIndex\n"
    "  pIndex index.space 0 swap number.magnitude to iSize\n"
    "\n"
    "  iSize grid::thisNodeName@ \\\"row: ('%v' %v)\\\" str.format\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes and table folder\n"
    "  popIndexes\n"
    "  popTable\n"
    "\n"
    "  pJob_SizeIndex job.response!\n"
    "  1 pJob_SizeIndex job.rowsProcessed!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_SizeIndex job check resources                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex::checkResources _eeh ( -- )\n"
    "\n"
    "  0 0 locals| sIndexNm sTableNm |\n"
    "\n"
    "  //checkResources received\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the table and index names\n"
    "  <indexNm> to sIndexNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  sTableNm sIndexNm checkSizeIndex not if job::this <ERROR_JOB> !!logError exit then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: sizeIndex :: sizeIndex <tableNm> <indexNm> ;\n"
    "jobSyntax: sizeIndex :: szIdx <tableNm> <indexNm> ;\n"
    "\n"
    "jobInfo: sizeIndex\n"
    "{\n"
    "  <?jobDesc?>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <?jobType?>  = JT_SIZEINDEX\n"
    "  <?jobKind?>  = JK_DIST2PC\n"
    "  <?rspKind?>  = RS_NODE_ROWS\n"
    "  <?ddlLock?>  = DL_GRAB_READ\n"
    "  \n"
    "  <?preCheck?> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_SizeIndex.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of grid_grid.sen

  sFileContents =
    "\""
    "\\\"munged grid_grid.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* grid.sen -- grid routines                                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" grid_grid.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* command path for SE                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\\\"../OS\\\\\\\\ X/Build/Products/Debug/SE\\\" constant SE_COMMAND\n"
    "//\\\"../OS\\\\\\\\ X/Build/Products/Release/SE\\\" constant SE_COMMAND\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* form the shell command for spawning and starting a node etc                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .formShellCommand ( bAdd sNodeName sNodeList -- \\\"<command>\\\" )\n"
    "\n"
    "  params| sNodeList |\n"
    "  params| sNodeName |\n"
    "  params| bAdd      |\n"
    "\n"
    "  //  \\\"nohup \\\"\n"
    "  \\\"\\\"\n"
    "\n"
    "  SE_COMMAND str.cat\n"
    "  \\\" --start\\\" str.cat\n"
    "  bAdd if\n"
    "    \\\" --addNode\\\" str.cat\n"
    "  then\n"
    "\n"
    "  \\\" --name \\\"  str.cat sNodeName str.cat sNodeList str.cat\n"
    "\n"
    "  \\\" --size \\\"              str.cat args.regionSize        >str   str.cat\n"
    "  \\\" --regionPrefix \\\"      str.cat args.regionPrefix             str.cat\n"
    "  \\\" --partitionsPerNode \\\" str.cat args.partitionsPerNode >str   str.cat\n"
    "  \\\" --subLoaders \\\"        str.cat args.subLoaders        >str   str.cat\n"
    "  \\\" --maxReadyLP \\\"        str.cat args.maxReadyLP        >str   str.cat\n"
    "// \\\" --commands /Users/ray/Desktop/rapidsse/Commands\\\"            str.cat\n"
    "\\\" --commands /Users/alkayamarti/rapidsSE/rapidsse/Commands\\\"   str.cat\n"
    "\n"
    "  args.tracepoint  if \\\" --tracepoint\\\"  str.cat then\n"
    "  args.verbose     if \\\" --verbose\\\"     str.cat then\n"
    "  args.dontFree    if \\\" --dontFree\\\"    str.cat then\n"
    "  args.freeCB      if \\\" --freeCB\\\"      str.cat then\n"
    "  args.metadata    if \\\" --metadata\\\"    str.cat then\n"
    "  args.log         if \\\" --log\\\"         str.cat then\n"
    "\n"
    "  \\\" &\\\" str.cat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* form the node list: {--node name ip port}*                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .formNodeList ( -- sNodeList )\n"
    "\n"
    "  locals| pNode |\n"
    "\n"
    "  \\\"\\\"\n"
    "\n"
    "  grid::definedNodes 0 do\n"
    "\n"
    "    I grid::node to pNode\n"
    "    pNode node.port\n"
    "    pNode node.IP\n"
    "    pNode node.name\n"
    "    \\\" --node %v %v %v\\\" str.format\n"
    "    str.cat\n"
    "\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn a specific node                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .spawnNamedNode ( bAdd sNodeName sNodeList -- )\n"
    "\n"
    "  params| sNodeList |\n"
    "  params| sNodeName |\n"
    "  params| bAdd      |\n"
    "\n"
    "  locals| sShellCommand |\n"
    "\n"
    "  // form the shell command\n"
    "  bAdd sNodeName sNodeList .formShellCommand to sShellCommand\n"
    "\n"
    "  // print the shell command\n"
    "  sShellCommand .\n"
    "\n"
    "  // execute the shell command\n"
    "  sShellCommand shell::execute\n"
    "\n"
    "  // check result\n"
    "  not assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn all other nodes for a grid on this machine                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::spawnOtherNodes ( -- )\n"
    "\n"
    "  // test for single node grid\n"
    "  grid::definedNodes 1 == if exit then\n"
    "\n"
    "  locals| sNodeList |\n"
    "  locals| sShellCommand |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // form the node list\n"
    "\n"
    "  .formNodeList to sNodeList\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // spawn all other nodes\n"
    "\n"
    "  grid::definedNodes 0 do\n"
    "\n"
    "    // all but this node\n"
    "    I grid::thisNode@ != if\n"
    "\n"
    "      // spawn/start node I\n"
    "      false  I grid::node node.name  sNodeList  .spawnNamedNode\n"
    "\n"
    "    then\n"
    "\n"
    "  loop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  grid::StartNode@ \\\"Cluster Start node: %v\\\" str.format .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn named node being added to a grid on this machine                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::spawnAddingNode ( sNodeNm -- )\n"
    "\n"
    "  params| sNodeNm   |\n"
    "\n"
    "  locals| sNodeList |\n"
    "\n"
    "  // form the node list\n"
    "  .formNodeList to sNodeList\n"
    "\n"
    "  // spawn/add node sNodeNm\n"
    "  true   sNodeNm   sNodeList  .spawnNamedNode\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set start node                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::setStartNode ( -- )\n"
    "\n"
    "  // set this node as the grid start node\n"
    "  grid::thisNode@ grid::StartNode!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forget named node (run by all participants)                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::forgetNode ( \\\"<NodeNm>\\\" )\n"
    "\n"
    "  params| sNodeNm |\n"
    "\n"
    "  sNodeNm grid::findNode node.forget\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT grid_grid.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of jobInfo.sen

  sFileContents =
    "\""
    "\\\"munged jobInfo.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* jobInfo.sen -- Job Info Compiler                                           */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" jobInfo.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": jobInfo::addEname params| sEvalue sEname |\n"
    "\n"
    "  compiler::current word.EnameSet@ locals| pEnameSet |\n"
    "\n"
    "  sEvalue find locals| pEvalueWord |\n"
    "\n"
    "  pEvalueWord if\n"
    "    pEvalueWord word.category@ tick rootConstant eql if\n"
    "\n"
    "      // sEvalue \\\"  %v is a constant\\\" .printf\n"
    "       sEname pEvalueWord execute pEnameSet EnameSet.addInt\n"
    "      exit\n"
    "\n"
    "    then\n"
    "  then\n"
    "\n"
    "  // -- -- --\n"
    "  sEname sEvalue pEnameSet EnameSet.addStr\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": findJobClassEnmSet ( sJobNm -- pEnameSet )\n"
    "\n"
    "  params| sJobNm |\n"
    "\n"
    "  sJobNm \\\"_cls\\\" str.cat find word.EnameSet@\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if the job is a generic job                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::isGenericJob\n"
    "\n"
    "  compiler::current word.EnameSet@ locals| pEnameSet |\n"
    "\n"
    "  \\\"<?jobKind?>\\\" pEnameSet EnameSet.getInt\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  JK_GENERIC\n"
    "  == if\n"
    "    // \\\"job::isGenericJob - job is a generic job\\\" .\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // \\\"job::isGenericJob - job is not a generic job\\\" .\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::isLocalJob\n"
    "\n"
    "  compiler::current word.EnameSet@ locals| pEnameSet |\n"
    "\n"
    "  \\\"<?jobKind?>\\\" pEnameSet EnameSet.getInt\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  JK_LOCAL\n"
    "  == if\n"
    "    // \\\"job::isLocalJob - job is a local job\\\" .\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // \\\"job::isLocalJob - job is not a local job\\\" .\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::isDistJob\n"
    "\n"
    "  compiler::current word.EnameSet@ locals| pEnameSet |\n"
    "\n"
    " \\\"<?jobKind?>\\\" pEnameSet EnameSet.getInt\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  JK_DIST2PC\n"
    "  == if\n"
    "    // \\\"job::isDistJob - job is a distributed job\\\" .\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // \\\"job::isDistJob - job is not a distributed job\\\" .\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::isServiceCmd\n"
    "\n"
    "  compiler::current word.EnameSet@ locals| pEnameSet |\n"
    "\n"
    "  \\\"<?cmdKind?>\\\" pEnameSet EnameSet.getInt\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  JK_DIST2PC\n"
    "  == if\n"
    "   // \\\"job::isDistJob - job is a distributed job\\\" .\n"
    "   true\n"
    "   exit\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // \\\"job::isDistJob - job is not a distributed job\\\" .\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": seedExists?\n"
    "\n"
    "  word::name_trunc swap str.cat\n"
    "    find if true else false then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": seedEnameAdd params| sDefaultSeed sSuffix sSeedEname |\n"
    "\n"
    "  compiler::current word.EnameSet@ locals| pEnameSet |\n"
    "\n"
    "  sSuffix seedExists?\n"
    "    if word::name_trunc else sDefaultSeed then\n"
    "      sSuffix str.cat  locals| pWordName |\n"
    "\n"
    "  sSeedEname pWordName pEnameSet EnameSet.addStr\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add default seeds for a distributed job                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .fillOutEnameSet_dist\n"
    "\n"
    "  \\\"<?SeedReq?>\\\" \\\"_req\\\" \\\"defaultSeedDist\\\" seedEnameAdd\n"
    "\n"
    "  \\\"<?SeedRcv?>\\\" \\\"_beg\\\" \\\"defaultSeedDist\\\" seedEnameAdd\n"
    "\n"
    "  \\\"<?SeedExe?>\\\" \\\"_exe\\\" \\\"defaultSeedDist\\\" seedEnameAdd\n"
    "\n"
    "  \\\"<?SeedEnd?>\\\" \\\"_end\\\" \\\"defaultSeedDist\\\" seedEnameAdd\n"
    "\n"
    "  \\\"<?SeedCan?>\\\" \\\"_can\\\" \\\"defaultSeedDist\\\" seedEnameAdd\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add default seeds for a local job                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .fillOutEnameSet_local\n"
    "\n"
    "  \\\"<?SeedReq?>\\\" \\\"_req\\\" \\\"defaultSeedLocal\\\" seedEnameAdd\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add default seeds for a generic job                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .fillOutEnameSet_generic\n"
    "\n"
    "  \\\"<?SeedRun?>\\\" \\\"_run\\\" \\\"defaultSeedLocal\\\" seedEnameAdd\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* populate the JobInfo ename-set with the names of the seeds for the job     */\n"
    "/* being compiled.  Use default seeds where appropropriate                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .fillOutEnameSet params| pEnameSet |\n"
    "\n"
    "  // default for command kind\n"
    "  \\\"<?cmdKind?>\\\" pEnameSet EnameSet.hasName not if\n"
    "    \\\"<?cmdKind?>\\\" \\\"CK_COMMAND\\\" jobInfo::addEname\n"
    "  then\n"
    "\n"
    "  // default for ddl lock\n"
    "  \\\"<?ddlLock?>\\\" pEnameSet EnameSet.hasName not if\n"
    "    \\\"<?ddlLock?>\\\" \\\"DL_NONE\\\" jobInfo::addEname\n"
    "  then\n"
    "\n"
    "  // default for job desc\n"
    "  \\\"<?jobDesc?>\\\" pEnameSet EnameSet.hasName not if\n"
    "    \\\"<?jobDesc?>\\\" \\\"--description of job--\\\" jobInfo::addEname\n"
    "  then\n"
    "\n"
    "  // default for job kind\n"
    "  \\\"<?jobKind?>\\\" pEnameSet EnameSet.hasName not if\n"
    "    \\\"<?jobKind?>\\\" \\\"JK_LOCAL\\\" jobInfo::addEname\n"
    "  then\n"
    "\n"
    "  // default for job type\n"
    "  \\\"<?jobType?>\\\" pEnameSet EnameSet.hasName not if\n"
    "    \\\"<?jobType?>\\\" \\\"JT_NONE\\\" jobInfo::addEname\n"
    "  then\n"
    "\n"
    "  // default for priority\n"
    "  \\\"<?priority?>\\\" pEnameSet EnameSet.hasName not if\n"
    "    \\\"<?priority?>\\\" \\\"PY_NORMAL\\\" jobInfo::addEname\n"
    "  then\n"
    "\n"
    "  // default for response kind\n"
    "  \\\"<?rspKind?>\\\" pEnameSet EnameSet.hasName not if\n"
    "    \\\"<?rspKind?>\\\" \\\"RS_NONE\\\" jobInfo::addEname\n"
    "  then\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  job::isgenericJob if\n"
    "    .fillOutEnameSet_generic\n"
    "  else\n"
    "  job::isDistJob if\n"
    "    .fillOutEnameSet_dist\n"
    "  else\n"
    "    .fillOutEnameSet_local\n"
    "  then then\n"
    "\n"
    "  // pEnameSet EnameSet.asStr .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* consume service arguments                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .consumeArgs\n"
    "\n"
    "  0 locals| nArgs |\n"
    "\n"
    "  //\\\".consumeArgs\\\" .\n"
    "\n"
    "  begin\n"
    "    next-token\n"
    "    dup \\\";&\\\" str.equal not\n"
    "  while\n"
    "    nArgs 1 + to nArgs\n"
    "  repeat\n"
    "\n"
    "  // drop the \\\";&\\\" from dstack\n"
    "  drop\n"
    "\n"
    "  nArgs\n"
    "\n"
    "  // for the moment we drop the arg vector from the data stack\n"
    "  dropN\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate two words, one which parses and another which spawns a service    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .generateService\n"
    "\n"
    "  // calc the name of the service\n"
    "  \\\"_\\\" compiler::current word.name@ str.removeSuffix locals| sServiceNm |\n"
    "\n"
    "  // calc the name of the spawner\n"
    "  sServiceNm \\\"_spawner\\\" str.cat locals| sSpawnerNm |\n"
    "\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // SPAWNER\n"
    "\n"
    "  // create a word by the spawner name\n"
    "  sSpawnerNm >create\n"
    "  compiler::current locals| pSpawnerWd |\n"
    "\n"
    "  // debug\n"
    "  //pSpawnerWd word.dump\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // -- encode the service spawning word -- -- -- -- -- --\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  sServiceNm , \\\"++ this is service spawner for: %v\\\" , POSTPONE .printf\n"
    "\n"
    "  sServiceNm , POSTPONE job::spawnUniversal\n"
    "\n"
    "  POSTPONE exit\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // debug\n"
    "  //pSpawnerWd word.dump\n"
    "\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // PARSER\n"
    "\n"
    "  // create an immediate word by the service name\n"
    "\n"
    "  sServiceNm >create\n"
    "  compiler::current locals| pServiceWd |\n"
    "  true pServiceWd word.immediate!\n"
    "\n"
    "  // debug\n"
    "  //pServiceWd word.dump\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // -- encode the service parsing word  -- -- -- -- -- --\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // in : <serviceNm> add call(.printf)\n"
    "  sServiceNm , \\\"++ this is the service parser for: %v\\\" , POSTPONE .printf\n"
    "\n"
    "  // in : <serviceNm> add call(.consumeArgs)\n"
    "  POSTPONE .consumeArgs\n"
    "\n"
    "  // in : <serviceNm> add code which adds call(` pSpawnerWd) in caller of service\n"
    "  pSpawnerWd , POSTPONE compile,\n"
    "\n"
    "  // in : <serviceNm> add exit\n"
    "  POSTPONE exit\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // debug\n"
    "  //pServiceWd word.dump\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* the job info compiler                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": jobInfo:\n"
    "\n"
    "  0 0 0 locals| sEname sEvalue pEnameSet |\n"
    "\n"
    "  // create a word using next token from input source as the word name\n"
    "  next-token \\\"_cls\\\" str.cat >create\n"
    "\n"
    "  // set the word kind to be jobClass\n"
    "  [ compiler::current , ] compiler::current word.category!\n"
    "\n"
    "  // attach an ename set to the word being created\n"
    "  EnameSet::new to pEnameSet\n"
    "\n"
    "  pEnameSet compiler::current word.EnameSet!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  \\\"<?jobNm?>\\\" word::name_trunc pEnameSet EnameSet.addStr\n"
    "\n"
    "  // skip the \\\"{\\\" token from input source\n"
    "  next-token drop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // parse each input token till \\\"}\\\", build ename set representing the syntax\n"
    "\n"
    "  begin\n"
    "    next-token\n"
    "    dup \\\"}\\\" str.equal not\n"
    "  while\n"
    "    to sEname\n"
    "    next-token drop\n"
    "    next-token to sEvalue\n"
    "    sEname sEvalue jobInfo::addEname\n"
    "  repeat\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // drop the \\\"}\\\" from dstack\n"
    "  drop\n"
    "\n"
    "  // get and drop \\\";\\\"\n"
    "  next-token drop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // complete the ename-set\n"
    "\n"
    "  //pEnameSet EnameSet.asStr .\n"
    "\n"
    "  pEnameSet .fillOutEnameSet\n"
    "\n"
    "  //pEnameSet EnameSet.asStr .\n"
    "\n"
    "  job::isServiceCmd if .generateService then\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT jobInfo.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_Start.sen

  sFileContents =
    "\""
    "\\\"munged job_Start.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Start.sen -- Start System                                              */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Start.sen\\\" .verbose\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* start system                                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": start_run ( -- <R> )\n"
    "\n"
    "  >>logEntry <SEED_RUN>\n"
    "\n"
    "  nullptr locals| pParentJob |\n"
    "\n"
    "  \\\"start_run\\\" .verbose\n"
    "\n"
    "  //supervisor ;&\n"
    "  periodic ;&\n"
    "  waker ;&\n"
    "\n"
    "  answer ;&\n"
    "  connector ;&\n"
    "\n"
    "  //service egArgA egArgB egArgC ;&\n"
    "\n"
    "  \\\"end start_run\\\" .verbose\n"
    "\n"
    "  <DONE_RUN>\n"
    "  job::completed\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Start.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job__Execute.sen

  sFileContents =
    "\""
    "\\\"munged job__Execute.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job__Execute.sen -- generic job related words                              */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job__Execute.sen\\\" .verbose\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on originating node                             //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distribute Job__Execute to all participants                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__Execute::distribute params| pJobOriginator |\n"
    "\n"
    "  //\n"
    "  // where: on the originator node\n"
    "  //\n"
    "\n"
    "  0 locals| pJob__Execute |\n"
    "\n"
    "  // create a temporary job__execute\n"
    "  pJobOriginator job__Execute::new to pJob__Execute\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // set the no of acks expected in originator job\n"
    "  grid::connectedNodes pJobOriginator job.acksRemaining!\n"
    "\n"
    "  // send job__execute to all nodes\n"
    "  grid::definedNodes 0\n"
    "  do\n"
    "    I grid::node node.isConnected if\n"
    "      I pJob__Execute job.forward\n"
    "    then\n"
    "  loop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // delete the temporary job__execute\n"
    "  pJob__Execute job.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* run received Job__Execute on participating node                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _Execute _run\n"
    "\n"
    "  //\n"
    "  // where: on the participating node\n"
    "  //\n"
    "  job::this locals| pJob__Execute |\n"
    "\n"
    "  // find the job to be executed in the participating jobs\n"
    "  pJob__Execute job.id@ locals| iJobId |\n"
    "  iJobId plist::findJob drop\n"
    "\n"
    "  // execute the job on this participating node\n"
    "  SEED_EXE JobRef[] job.seed!\n"
    "  JobRef[] job.spawn\n"
    "  JobRef[].return\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: _Execute :: _Execute ;\n"
    "\n"
    "jobInfo: _Execute\n"
    "{\n"
    "  <?jobDesc?>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <?jobKind?>  = JK_GENERIC\n"
    "}\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job__Execute.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of prompt.sen

  sFileContents =
    "\""
    "\\\"munged prompt.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* prompt.sen -- prompt related words                                         */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"-prompt.sen\\\" .verbose\n"
    "\n"
    ": article_dump prompt article::dump ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT prompt.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_WriteRow.sen

  sFileContents =
    "\""
    "\\\"munged job_WriteRow.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_WriteRow.sen -- Write Row Job                                          */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_WriteRow.sen\\\" .verbose\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                               on kid node                                  //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* write row into the table                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": WriteRow.insert ( pJob_WriteRow -- )\n"
    "\n"
    "  params| pJob_WriteRow |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  0 locals| pJob_InsertRow  |\n"
    "\n"
    "  0 locals| sTableNm    |\n"
    "  0 locals| i_Partition |\n"
    "  0 locals| bAllLoaded  |\n"
    "  0 locals| pJob_Parent |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  \\\"WriteRow.insert :\\\" .verbose\n"
    "  //pJob_WriteRow job.show\n"
    "\n"
    "  // get table name\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  // use table name find and set target table\n"
    "  sTableNm find execute locals| pTable |\n"
    "  pTable pJob_WriteRow Job_WriteRow.table!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the parent job (participant node)\n"
    "  // parent jo can be EndInsert of LoadTable\n"
    "  pJob_WriteRow Job_WriteRow.parentJobId@ locals| iParentJobId |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // grab write lock on table partition\n"
    "  pJob_WriteRow Job_WriteRow.partition@ to i_Partition\n"
    "  i_Partition pTable tablePtnGrabWrite\n"
    "\n"
    "  // now insert the Row of rows\n"
    "  pJob_WriteRow Job_WriteRow.insertRow\n"
    "\n"
    "  // drop write lock on table partition\n"
    "  i_Partition pTable tablePtnDropWrite\n"
    "\n"
    "  // we wait till the parent job can be found in the participant job skip list\n"
    "  pJob_WriteRow iParentJobId job::waitParticipant to pJob_Parent\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // first check if the job is executing SS_SEED_EXE\n"
    "  // then get the task that is executing it\n"
    "  begin\n"
    "    pJob_Parent job.IsExecuting\n"
    "  not while\n"
    "    1 thread::sleepMsec\n"
    "  repeat\n"
    "\n"
    "  pJob_Parent job.task@ locals| pTask_Parent |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // wait for acks to be set in the endInsert task\n"
    "  begin\n"
    "     pTask_Parent task.IsAckSet\n"
    "  not while\n"
    "     1 thread::sleepMsec\n"
    "  repeat\n"
    "\n"
    "  \\\"WriteRow.insert acking parentJob(insertRow):\\\" .verbose\n"
    "  pTask_Parent task.grabLock\n"
    "  pTask_Parent task.dropLock\n"
    "  pTask_Parent task.ack\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* seed on kid node                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": writeRow_kid ( -- )\n"
    "\n"
    "  >>logEntry <SEED_RUN>\n"
    "\n"
    "  job::this locals| pJob_WriteRow |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check there is enough Rows and load\n"
    "\n"
    "  // node::checkEnoughRows if\n"
    "  pJob_WriteRow writeRow.insert\n"
    "  //then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  <<logExit\n"
    "  job::deleteThis\n"
    "\n"
    "  <DONE_KID>\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on loading node                                 //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forward this load Row job to kid node                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": WriteRow.forward ( pJob_WriteRow -- )\n"
    "\n"
    "  params| pJob_WriteRow |\n"
    "\n"
    "  // which partition are we forwarding to?\n"
    "  pJob_WriteRow Job_WriteRow.partition@ locals| i_Partition |\n"
    "\n"
    "  // convert i_Partition to i_ForwardNode\n"
    "  i_Partition grid::toNode locals| i_ForwardNode |\n"
    "\n"
    "  //i_Partition i_ForwardNode \\\"WriteRow.forward : Node %v Partition %v\\\" .printf\n"
    "\n"
    "  // send this job to the forward node\n"
    "  i_ForwardNode pJob_WriteRow job.forward\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* seed on writing node                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": writeRow_run (  -- )\n"
    "\n"
    "  >>logEntry <SEED_RUN>\n"
    "\n"
    "  job::this locals| pJob_WriteRow  |\n"
    "\n"
    "  \\\"writeRow_run :\\\" .verbose\n"
    "\n"
    "  // simply forward this job to kid node\n"
    "  pJob_WriteRow writeRow.forward\n"
    "\n"
    "  job::deleteThis\n"
    "\n"
    "  <DONE_RUN>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_WriteRow.sen"_Stz
  ;

  vCompileConstant(sFileContents);


