  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_StartCluster.sen

  sFileContents =
    "\""
    "\\\"munged job_StartCluster.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_StartCluster.sen -- Job Start Cluster                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_StartCluster.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": node.isConnected ( pNode -- t|f )\n"
    "\n"
    "  params| pNode |\n"
    "\n"
    "  pNode node.sendSocket@ if\n"
    "    true\n"
    "  else\n"
    "    false\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::connected ( -- t|f )\n"
    "\n"
    "  grid::definedNodes 0\n"
    "  do\n"
    "    I grid::node node.isConnected not if\n"
    "      args.verbose if\n"
    "        I \\\"Node no %v not connected\\\" .printf\n"
    "      then\n"
    "      unloop\n"
    "      false\n"
    "      exit\n"
    "    then\n"
    "  loop\n"
    "\n"
    "  \\\"All nodes connected\\\" .verbose\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::pause ( -- )\n"
    "\n"
    "  begin\n"
    "    grid::connected not\n"
    "  while\n"
    "    100 thread::sleepMsec\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gridTest\n"
    "\n"
    "  grid::definedNodes 0\n"
    "  do\n"
    "    I grid::node node.isConnected\n"
    "    I \\\"gridTest: node no %v connected %v \\\" .printf\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gridWait\n"
    "\n"
    "  grid::pause\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request to wait for cluster to start (on originating node)                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": startCluster_req ( -- <R> )\n"
    "\n"
    "\n"
    "  task::seedInitially\n"
    "\n"
    "  // [ compiler::current word.name@ , ] .\n"
    "  // <jobNm> .\n"
    "\n"
    "  job::becomeOriginator\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // has cluster already been started?\n"
    "\n"
    "  grid::started@ if\n"
    "                                             //! how do we set an error message?\n"
    "    <DONE_REQ>\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // spawn all other nodes\n"
    "\n"
    "  grid::setStartNode\n"
    "\n"
    "  grid::spawnOtherNodes\n"
    "\n"
    "  //connector::spawn\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pause till all nodes connected\n"
    "\n"
    "  grid::pause\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the start cluster job\n"
    "\n"
    "  job::distributeConnected\n"
    "\n"
    "  // wait for the signal from deciding job__ended/cancelled\n"
    "  task::wait\n"
    "\n"
    "  // set grid as started\n"
    "  true grid::started!\n"
    "  \\\"Cluster started\\\" .\n"
    "\n"
    "  task::doneFinally\n"
    "\n"
    "  //\\\"Signalling waiting thread\\\" .\n"
    "  job::this job.signalWaiter\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute job_StartCluster (on participating node)                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": startCluster::execute _eeh ( -- )\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // wait till all nodes connected\n"
    "  grid::pause\n"
    "\n"
    "  true grid::started!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: startCluster :: startCluster ;\n"
    "\n"
    "jobInfo: startCluster\n"
    "{\n"
    "  <?jobKind?>  = JK_DIST2PC\n"
    "  <?rspKind?>  = RS_NONE\n"
    "  <?ddlLock?>  = DL_NONE\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\""
  " CONSTANT job_StartCluster.sen"_Stz
  ;

  vCompileConstant(sFileContents);


