  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of db_table.sen

  sFileContents =
    "\""
    "\\\"munged db_table.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_table.sen -- table related words                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" db_table.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* table is used as a kind of word to identify tables                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table ;\n"
    "\n"
    "//: makeTables pathPush \\\"tables\\\" :dic tick folder swap execute dic.kind! pathDrop ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a tables folder under given named schema                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeTables ( \\\"<schemaNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING TABLES FOR SCHEMA \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"tables\\\"     ( dic \\\"tables\\\" )\n"
    "  swap         ( \\\"tables\\\" dic )\n"
    "  :folder      ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a tableNm folder under tables                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeTableDic ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING TABLE DIC \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  pathCurrentFolder\n"
    "  :folder      ( )\n"
    " ;\n"
    "\n"
    "\n"
    ": isTable word.category@ tick table eql ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a table using name from input stream (doesnt leave table on stk)    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table:\n"
    "\n"
    "  createPersistent\n"
    "  WK_OBJECT compiler::current word.kind!\n"
    "  sizeof_table allot\n"
    "  compiler::current >body object.magic!\n"
    "  CN_TABLE compiler::current >body object.class!\n"
    "  compiler::current >body table.init\n"
    "  true compiler::current >body object.wordbody!\n"
    "  tick table compiler::current word.category!\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a table using name on the stack (leaves table on stack)             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :table\n"
    "\n"
    "  >createPersistent\n"
    "  WK_OBJECT compiler::current word.kind!\n"
    "  sizeof_table allot\n"
    "  compiler::current >body object.magic!\n"
    "  CN_TABLE compiler::current >body object.class!\n"
    "  compiler::current >body table.init\n"
    "  true compiler::current >body object.wordbody!\n"
    "  tick table compiler::current word.category!\n"
    "  compiler::current\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if this task dic path ends in tables                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinTables ( -- t|f )\n"
    "\n"
    "  pathCurrentFolder dic.name \\\"tables\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* assert top of task dictionary stack is tables                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertInTables ( -- t|f )\n"
    "\n"
    "  withinTables assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check top of task dictionary stack is tables                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInTables ( -- t|f )\n"
    "\n"
    "  withinTables if true exit then\n"
    "\n"
    "  EC_NOT_IN_TABLES false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if column is a valid column of the table                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsColumn ( \\\"<columnNm>\\\" \\\"<tableNm>\\\"-- t|f )\n"
    "\n"
    "  params| sTableNm sColumnNm |\n"
    "  0 locals| pTable |\n"
    "\n"
    "  sTableNm find execute to pTable\n"
    "  sColumnNm pTable table.isColumn if true exit then\n"
    "\n"
    "  EC_INVALID_COLUMN false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if this task dic path is same name as argument                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinTable ( \\\"<tableNm>\\\" -- t|f )\n"
    "\n"
    "  assert::stack_1+\n"
    "  CN_STZVAL assert::class_0\n"
    "\n"
    "  // assert dictionary path\n"
    "  task::this task.dicStack dicStack.depth assert\n"
    "\n"
    "  pathCurrentFolder dic.name str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check top of task dictionary stack is given table name                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInTable ( \\\"<tableNm>\\\" -- t|f )\n"
    "\n"
    "  withinTable if true exit then\n"
    "\n"
    "  EC_NOT_IN_TABLE false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check given name is a table                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  find ( \\\"<tableNm>\\\" ^w:table )\n"
    "\n"
    "  dup ( \\\"<tableNm>\\\" ^w:table ^w:table )\n"
    "  not ( \\\"<tableNm>\\\" ^w:table bool )\n"
    "  if\n"
    "    drop ( \\\"<tableNm>\\\" )\n"
    "    drop ( )\n"
    "    EC_NO_SUCH_TABLE false ( errorCode false )\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  dup ( \\\"<tableNm>\\\" ^w:table ^w:table )\n"
    "\n"
    "  word.category@ ( \\\"<tableNm>\\\" ^w:table ^word )\n"
    "  tick table ( \\\"<tableNm>\\\" ^w:table ^word ^word )\n"
    "  eql ( \\\"<tableNm>\\\" ^w:table bool )\n"
    "  if\n"
    "    drop ( \\\"<tableNm>\\\" )\n"
    "    true ( \\\"<tableNm>\\\" true )\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  drop ( \\\"<tableNm>\\\" )\n"
    "  drop ( )\n"
    "  EC_NOT_A_TABLE false ( errorCode false )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check there is a table folder                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsTableFolder  ( \\\"<tableName>\\\" -- )\n"
    "\n"
    "  findInCurrent not if EC_NO_SUCH_TABLE false exit then\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the table folder and push it onto task dictionary                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushTable ( \\\"<tableName>\\\" -- )\n"
    "\n"
    "  find execute pathPush\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the table folder                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popTable\n"
    "\n"
    "  pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find table given its name                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table::find ( sTableNm -- pTable )\n"
    "\n"
    "  dup \\\"table::find %v\\\" str.format .logNote\n"
    "\n"
    "  find execute\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT db_table.sen"_Stz
  ;

  vCompileConstant(sFileContents);


