  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_ListIndexes.sen

  sFileContents =
    "\""
    "\\\"munged job_ListIndexes.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_ListIndexes.sen -- Job list Indexes                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_ListIndexes.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list indexes of a table                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listIndexes ( Job_ListIndexes -- )\n"
    "\n"
    "  params| pJob_ListIndexes |\n"
    "\n"
    "  0 0 0 0 locals| iCount pIndex iColumns pTable |\n"
    "\n"
    "  \\\"\\\"   // initial contents of the string\n"
    "  pathCurrentFolder dic.lastWord dup\n"
    "  iterate                         // setup iteration of words\n"
    "\n"
    "    // get the index ptr\n"
    "    object@ word.name@ findInCurrent execute to pIndex\n"
    "\n"
    "    // increment count\n"
    "    1 iCount + to iCount\n"
    "\n"
    "    // index a primary key ?\n"
    "    pIndex index.isPrimaryKey@\n"
    "    if \\\"true\\\" else \\\"false\\\" then\n"
    "\n"
    "    // index is unique ?\n"
    "    pIndex index.isUnique@\n"
    "    if \\\"true\\\" else \\\"false\\\" then\n"
    "\n"
    "    // add word kind to ls string\n"
    "    object@ word.name@\n"
    "\n"
    "    \\\"row: ( '%v',%v,%v )\\\\n\\\" str.format\n"
    "    str.cat\n"
    "\n"
    "    object@ word.prev object!       // step backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set response in the job\n"
    "  pJob_ListIndexes job.response!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // sent rows Processed in the job\n"
    "  iCount pJob_ListIndexes job.rowsProcessed!\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* List Indexes requests (on the originating node)                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lsidx_req ( -- <R> )\n"
    "\n"
    "  >>logEntry <SEED_REQ>\n"
    "\n"
    "  0 0 0 0 locals| sTableNm iCount pJob_ListIndexes pTask |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_ListIndexes\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if pJob_ListIndexes <ERROR_REQUEST> !!logError exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get table name from job\n"
    "  //pJob_ListIndexes job.objectName@ to sTableNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if pJob_ListIndexes <ERROR_REQUEST> !!logError exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is a table\n"
    "  sTableNm checkIsTable not if popTable pJob_ListIndexes <ERROR_REQUEST> !!logError exit then\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(name VARCHAR, isUnique BOOLEAN, isPrimaryKey BOOLEAN)\\\"\n"
    "       pJob_ListIndexes job.metadata!\n"
    "  then\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // list table columns\n"
    "  pJob_ListIndexes listIndexes\n"
    "\n"
    "  // pop indexes folder\n"
    "  popIndexes\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // pop table dictionary\n"
    "  popTable\n"
    "  assertInTables\n"
    "\n"
    "  <<logExit <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: lsidx :: lsidx <tableNm> ;\n"
    "\n"
    "jobInfo: lsidx\n"
    "{\n"
    "  <?jobDesc?>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <?jobType?>  = JT_LISTINDEXES\n"
    "  <?jobKind?>  = JK_LOCAL\n"
    "  <?rspKind?>  = RS_LOCAL_ROWS\n"
    "  <?ddlLock?>  = DL_GRAB_READ\n"
    "  \n"
    "  <?preCheck?> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_ListIndexes.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_Sanity.sen

  sFileContents =
    "\""
    "\\\"munged job_Sanity.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Sanity.sen -- Job Sanity                                               */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Sanity.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request to get sanity of nodes in the grid (on originating node)           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_req ( -- <R> )\n"
    "\n"
    "  >>logEntry <SEED_REQ>\n"
    "\n"
    "  0 0 locals| pJob pTask |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    \\\"(nodeName VARCHAR, sanity VARCHAR)\\\"\n"
    "  pJob job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the job\n"
    "  pJob job.distribute\n"
    "\n"
    "  <<logExit <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_Sanity job                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_exe ( pJob_Sanity -- )\n"
    "\n"
    "  >>logEntry <SEED_EXE>\n"
    "\n"
    "  //params| pJob_Sanity |\n"
    "  job::this locals| pJob_Sanity |\n"
    "\n"
    "  0 0 locals| iSize iPartitions |\n"
    "\n"
    "  CN_JOB_SANITY pJob_Sanity object.assertClass\n"
    "\n"
    "  //\\\"GETTING SANITY on NODE \\\" grid::thisNode@ >str str.cat .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the node size of originating node from the job\n"
    "  pJob_Sanity job.regionSize@ to iSize\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the no of partitions of originating node from the job\n"
    "  pJob_Sanity job.partitions@ to iPartitions\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  args.tracepoint if\n"
    "    \\\"GETTING PARTITIONS on NODE \\\" grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  iPartitions node.partitions == not if\n"
    "    EC_CLUSTER_PARTITIONS_MISMATCH\n"
    "    pJob_Sanity <ERROR_JOB>\n"
    "  else\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    args.tracepoint if\n"
    "      \\\"GETTING SIZE on NODE \\\"grid::thisNode@ >str str.cat .\n"
    "    then\n"
    "\n"
    "    iSize node.size == not if\n"
    "      EC_CLUSTER_SIZE_MISMATCH\n"
    "      pJob_Sanity <ERROR_JOB>\n"
    "    else\n"
    "      \\\"row: ('\\\"\n"
    "      grid::thisNodeName@ str.cat\n"
    "       \\\"','sanity check passed')\\\" str.cat\n"
    "      pJob_Sanity job.response!\n"
    "    then\n"
    "\n"
    "  then\n"
    "\n"
    "  1 pJob_Sanity job.rowsProcessed!\n"
    "\n"
    "  pJob_Sanity job.notice\n"
    "\n"
    "  pJob_Sanity job::participantExecuted\n"
    "\n"
    "  <<logExit <DONE_EXE>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_beg ( -- )\n"
    "\n"
    "  >>logEntry <SEED_BEG>\n"
    "\n"
    "  job::this locals| pJob_sanity |\n"
    "\n"
    "  pJob_sanity job.becomeParticipant\n"
    "\n"
    "  job::participantBegun\n"
    "\n"
    "  <<logExit <DONE_BEG>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_end ( -- )\n"
    "\n"
    "  >>logEntry <SEED_END>\n"
    "\n"
    "  job::this locals| pJob_sanity |\n"
    "\n"
    "  job::participantEnded\n"
    "\n"
    "  <<logExit <DONE_END>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_can ( -- )\n"
    "\n"
    "  >>logEntry <SEED_CAN>\n"
    "\n"
    "  job::this locals| pJob_sanity |\n"
    "\n"
    "  job::participantCancelled\n"
    "\n"
    "  <<logExit <DONE_CAN>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\""
  " CONSTANT job_Sanity.sen"_Stz
  ;

  vCompileConstant(sFileContents);


