  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_SubInserter.sen

  sFileContents =
    "\""
    "\\\"munged job_SubInserter.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* Job_SubInserter.sen -- Job Insert Rows                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" Job_SubInserter.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* job_InsertRow request (on originating node)                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": SubInserter_req (  -- <R> )\n"
    "\n"
    "  >>logEntry <SEED_REQ>\n"
    "\n"
    "  0 locals| pThisTask |\n"
    "  0 0 0 locals| pJob_SubInserter sTableNm pTable |\n"
    "\n"
    "\n"
    "  // get the task\n"
    "  task::this to pThisTask\n"
    "\n"
    "  // get the job from the task\n"
    "  pThisTask task.job@ to pJob_SubInserter\n"
    "  //pJob_SubInserter pThisTask \\\"InsertRow_req task: %v job_InsertRow %v\\\" .printf\n"
    "\n"
    "  // distribute the job\n"
    "  //Job_InsertRow job.distribute\n"
    "\n"
    "  //pJob_SubInserter job.objectName@ to sTableNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  sTableNm find execute locals| pTable |\n"
    "\n"
    "  pTable pJob_SubInserter Job_SubInserter.begin\n"
    "\n"
    "  // add job to originator jobs\n"
    "  //pJob_SubInserter job.addOriginator\n"
    "\n"
    "  <<logExit <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_SubInserter job check resources                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": SubInserter.checkResources ( pJob_SubInserter -- )\n"
    "\n"
    "  >>logEntry <Check_Resources>\n"
    "\n"
    "  params| pJob_SubInserter  |\n"
    "\n"
    "  //pJob_SubInserter job.objectName@ locals| sTableNm |\n"
    "  <tableNm> locals| sTableNm |\n"
    "\n"
    "  //checkResources received\\\" .\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // grab a ddl lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // path checks\n"
    "\n"
    "  // set task's dictionary stack from path in job\n"
    "  //pJob_SubInserter job.pushPath task::dicStack.set\n"
    "  //pushPath strVec::toPath to <path>\n"
    "  <path> str.toStrVec task::dicStack.set\n"
    "  //pathDump\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if pJob_SubInserter <ERROR_JOB> !!logError exit then\n"
    "  //sTableNm \\\"In table folder: %v\\\" .printf\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert\n"
    "  //pathDump\n"
    "\n"
    "  // check it is a table\n"
    "  sTableNm checkIsTable not if popTable pJob_SubInserter <ERROR_JOB> !!logError exit then\n"
    "  drop\n"
    "\n"
    "  // pop table dictionary\n"
    "  popTable\n"
    "  //pathDump\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // check if we have enough buffers\n"
    "\n"
    "  node::checkEnoughBuffers not if pJob_SubInserter <ERROR_JOB> !!logError exit then\n"
    "\n"
    "  <<logExit <Resources_Checked>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_SubInserter job release resources                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": SubInserter.releaseResources ( pJob_SubInserter -- )\n"
    "\n"
    "  >>logEntry <Release_Resources>\n"
    "\n"
    "  params| pJob_SubInserter  |\n"
    "\n"
    "  //releaseResources received\\\" .\n"
    "\n"
    "  <<logExit <Resources_Released>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_SubInserter.sen"_Stz
  ;

