  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of JobSeeds.sen

  sFileContents =
    "\""
    "\\\"munged JobSeeds.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* jobSeeds.sen -- Default Job Seeds                                          */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" jobSeeds.sen\\\" .verbose\n"
    "\n"
    "\n"
    "/******************************************************************************/\n"
    "/**                                LOCAL JOBS                                **/\n"
    "/******************************************************************************/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request default                                      (on originating node) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": defaultSeedLocal _req ( -- )\n"
    "\n"
    "  task::seedInitially\n"
    "\n"
    "  [ compiler::current word.name@ , ] .\n"
    "  <jobNm> .\n"
    "\n"
    "  //debug::breakPoint\n"
    "\n"
    "  <path> str.toStrVec task::dicStack.set\n"
    "\n"
    "  job::acquireDdlLock\n"
    "\n"
    "  <jobNm> \\\"::request\\\" str.cat find dup if\n"
    "    execute\n"
    "  else\n"
    "    drop\n"
    "  then\n"
    "\n"
    "  DdlLock[].testDrop\n"
    "\n"
    "  task::doneFinally\n"
    "\n"
    "  //\\\"Signalling waiting thread\\\" .\n"
    "  job::this job.signalWaiter\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "\n"
    "/******************************************************************************/\n"
    "/**                             DISTRIBUTED JOBS                             **/\n"
    "/******************************************************************************/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                          - Originating Node -                          ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request default                                      (on originating node) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": defaultSeedDist _req ( -- )\n"
    "\n"
    "  task::seedInitially\n"
    "\n"
    "  // [ compiler::current word.name@ , ] .\n"
    "  // <jobNm> .\n"
    "\n"
    "  job::becomeOriginator\n"
    "\n"
    "  job::distributeConnected\n"
    "\n"
    "  // wait for the signal from deciding job__ended/cancelled\n"
    "  task::wait\n"
    "\n"
    "  //job::this job.removeOriginator  // this is currently being done by job_ended\n"
    "\n"
    "  task::doneFinally\n"
    "\n"
    "  //\\\"Signalling waiting thread\\\" .\n"
    "  job::this job.signalWaiter\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                       - Participating Nodes -                          ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin default                                 (on each participating node) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": defaultSeedDist _beg ( -- )\n"
    "\n"
    "  task::seedInitially\n"
    "\n"
    "  // [ compiler::current word.name@ , ] .\n"
    "\n"
    "  JP_BEGINNING job::this job.phase!\n"
    "\n"
    "  <path> str.toStrVec task::dicStack.set\n"
    "\n"
    "  job::becomeParticipant\n"
    "\n"
    "  <jobNm> \\\"::checkResources\\\" str.cat find dup if\n"
    "    execute\n"
    "  else\n"
    "    drop\n"
    "  then\n"
    "\n"
    "  JP_BEGUN job::this job.phase!\n"
    "\n"
    "  2pcReply::job__begun\n"
    "\n"
    "  task::doneFinally\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute default                               (on each participating node) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": defaultSeedDist _exe\n"
    "\n"
    "  task::seedInitially\n"
    "\n"
    "  // [ compiler::current word.name@ , ] .\n"
    "\n"
    "  JP_EXECUTING job::this job.phase!\n"
    "\n"
    "  // ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! !\n"
    "  // set task's dictionary stack from path in job\n"
    "\n"
    "  <path> str.toStrVec task::dicStack.set\n"
    "  //task::dump\n"
    "\n"
    "  job::acquireDdlLock\n"
    "\n"
    "  <jobNm> \\\"::execute\\\" str.cat find dup if\n"
    "    execute\n"
    "  else\n"
    "    drop\n"
    "  then\n"
    "\n"
    "  JP_EXECUTED job::this job.phase!\n"
    "\n"
    "  2pcReply::job__executed\n"
    "\n"
    "  task::doneFinally\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end default                                   (on each participating node) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": defaultSeedDist _end ( -- )\n"
    "\n"
    "  task::seedInitially\n"
    "\n"
    "  // [ compiler::current word.name@ , ] .\n"
    "\n"
    "  JP_ENDING job::this job.phase!\n"
    "\n"
    "  <jobNm> \\\"::releaseResources\\\" str.cat find dup if\n"
    "    execute\n"
    "  else\n"
    "    drop\n"
    "  then\n"
    "\n"
    "  JP_ENDED job::this job.phase!\n"
    "\n"
    "  job::this job.removeParticipant\n"
    "\n"
    "  2pcReply::job__ended\n"
    "\n"
    "  task::doneFinally\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel default                                (on each participating node) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": defaultSeedDist _can ( -- )\n"
    "\n"
    "  task::seedInitially\n"
    "\n"
    "  // [ compiler::current word.name@ , ] .\n"
    "\n"
    "  JP_CANCELING job::this job.phase!\n"
    "\n"
    "  <jobNm> \\\"::releaseResources\\\" str.cat find dup if\n"
    "    execute\n"
    "  else\n"
    "    drop\n"
    "  then\n"
    "\n"
    "  JP_CANCELED job::this job.phase!\n"
    "\n"
    "  job::this job.removeParticipant\n"
    "\n"
    "  2pcReply::job__cancelled\n"
    "\n"
    "  task::doneFinally\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT JobSeeds.sen"_Stz
  ;

  vCompileConstant(sFileContents);


