  // munge of job_VerifyIndex.sen

  sFileContents =
    "\""
    "\\\"munged job_VerifyIndex.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_VerifyIndex.sen -- Job Verify Index                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_VerifyIndex.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a valid table folder                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkVerifyIndex ( \\\"<tableNm>\\\" \\\"<indexNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sIndexNm sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWord not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "  //sTableNm tableInUse if popTable EC_TABLE_IN_USE false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is an index we are dropping\n"
    "  sIndexNm checkIsIndex not if\n"
    "    popIndexes popTable assertInTables false exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes and table folder\n"
    "  popIndexes\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify index request on a node                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": verifyIndex::execute _eeh ( -- )\n"
    "\n"
    "  job::this locals| pJob_VerifyIndex |\n"
    "\n"
    "  0 0 0 0 locals| pTask pIndex sTableNm sIndexNm  |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the table and index names\n"
    "  <indexNm> to sIndexNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table and indexes folder\n"
    "  sTableNm pushTable assert\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // visualize\n"
    "  sIndexNm find execute index.verify\n"
    "  sTableNm sIndexNm grid::thisNodeName@\n"
    "  \\\"row: ('%v', '%v', '%v', '%v')\\\\n\\\" str.format\n"
    "  pJob_VerifyIndex job.response!\n"
    "  1 pJob_VerifyIndex job.rowsProcessed!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes and table folder\n"
    "  popIndexes\n"
    "  popTable\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_VerifyIndex job check resources                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": verifyIndex::checkResources _eeh ( -- )\n"
    "\n"
    "  0 0 locals| sIndexNm sTableNm |\n"
    "\n"
    "  //checkResources received\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  <indexNm> to sIndexNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  sTableNm sIndexNm checkVerifyIndex not if job::this <ERROR_JOB> !!logError exit then\n"
    "\n"
    "  DdlLock[].dropRead\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "jobSyntax: verifyIndex :: verifyIndex <tableNm> <indexNm> ;\n"
    "jobSyntax: verifyIndex :: vfyIdx <tableNm> <indexNm> ;\n"
    "\n"
    "jobInfo: verifyIndex\n"
    "{\n"
    "  <?jobDesc?>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <?jobType?>  = JT_VERIFYINDEX\n"
    "  <?jobKind?>  = JK_DIST2PC\n"
    "  <?rspKind?>  = RS_NODE_ROWS\n"
    "  <?ddlLock?>  = DL_GRAB_READ\n"
    "  \n"
    "  <?preCheck?> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_VerifyIndex.sen"_Stz
  ;

  vCompileConstant(sFileContents);


