    "  \\\": select_req END\\\" .\n"
    "\n"
    "  900 ssn::senLoc\n"
    "\n"
    "  <<logExit <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Select.sen"_Stz
  ;

