  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_Pwf.sen

  sFileContents =
    "\""
    "\\\"munged job_Pwf.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Pwf.sen -- Job Present Working Folder                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Pwf.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pwf command request                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pwf_req ( -- <R> )\n"
    "\n"
    "  >>logEntry <SEED_REQ>\n"
    "  //\\\">>pwf_req\\\" log::mark\n"
    "\n"
    "  100 ssn::senLoc\n"
    "\n"
    "  0 0 0 0 locals| pJob_Pwf pTask |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_Pwf\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    \\\"(path VARCHAR)\\\" pJob_Pwf job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // start of working string\n"
    "  \\\"row: ('/\\\"\n"
    "\n"
    "  // iterate thru each folder in path and concat to end\n"
    "  pathDepth 0 do\n"
    "    // compute the path subscript\n"
    "    pathDepth 1 - I -\n"
    "    // pick the path, get its name and concat name to working string\n"
    "    pathPick dic.name str.cat\n"
    "    // concat \\\"/\\\" to end of working string\n"
    "    \\\"/\\\" str.cat\n"
    "  loop\n"
    "\n"
    "  // end working string\n"
    "  \\\"')\\\\n\\\" str.cat\n"
    "\n"
    "  pJob_Pwf job.response!\n"
    "  1 pJob_Pwf job.rowsProcessed!\n"
    "\n"
    "  900 ssn::senLoc\n"
    "\n"
    "  //\\\"<<pwf_req\\\" log::mark\n"
    "    <<logExit <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: pwf :: pwf ;\n"
    "\n"
    "jobInfo: pwf\n"
    "{\n"
    "  <?jobDesc?>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <?jobType?>  = JT_PWF\n"
    "  <?jobKind?>  = JK_LOCAL\n"
    "  <?rspKind?>  = RS_LOCAL_ROWS\n"
    "  <?ddlLock?>  = DL_GRAB_READ\n"
    "  \n"
    "  <?preCheck?> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Pwf.sen"_Stz
  ;

  vCompileConstant(sFileContents);


